import math


def rc_time_constant(resistance_ohm, capacitance_f):
    if resistance_ohm <= 0 or capacitance_f <= 0:
        raise ValueError("resistance_ohm and capacitance_f must be positive")
    return resistance_ohm * capacitance_f


def charge_fraction(elapsed_s, tau_s):
    if tau_s <= 0:
        raise ValueError("tau_s must be positive; a zero time constant has no curve")
    return 1 - math.exp(-elapsed_s / tau_s)


tau_s = rc_time_constant(10_000.0, 100e-6)
print(f"RC time constant tau = {tau_s:.2f} s")
for t_s in (1.0, 2.0, 5.0):
    v_c = 5.0 * charge_fraction(t_s, tau_s)
    print(f"t = {t_s:.1f} s -> V_C = {v_c:.2f} V")
assert abs(tau_s - 1.0) < 1e-12
assert abs(charge_fraction(1.0, 1.0) - 0.6321205588285577) < 1e-12
assert abs(charge_fraction(5.0, 1.0) - 0.9932620530009145) < 1e-12
